import type { SystemStyleObject } from '@chakra-ui/react';
import { HOVER_CAPABLE_QUERY } from '../../zimmProductCardShared';

// Figma "Image Group" component set, node 40002742:46323. The Large variant (40002742:46322,
// 288x432) and the Small/mobile variant (40002742:46321, 179x268) both resolve to the same
// ~2:3 ratio (288/432 = 0.667; 179/268 = 0.668) — expressed here as a ratio, not either
// variant's sampled pixel dimensions, per the card's "fluid, not a fixed px width" contract.
const ASPECT_RATIO = '2 / 3';

// Arrows and the touch slide-indicator are mutually exclusive by pointer capability, matching
// the resolved SFCC-236 decision confirmed directly in the Figma structure: the Large
// (hover-capable) variant carries the Carousel arrows with no indicator; the Small (touch)
// variant carries the indicator with no Carousel. `HOVER_CAPABLE_QUERY` itself now lives in
// `zimmProductCardShared.ts` — shared with `zimmProductCard.css.ts`'s own identical gate — rather
// than being retyped here.

/**
 * Recipe for the product-card media block (ui-kits/molecules/zimmProductCardMedia). Parts:
 *   - `root` / `scrollContainer` / `slide` — the always-present scroll-snap structure.
 *   - `image` — a plain (non-hover-swap) slide's own <img>.
 *   - `hoverSwapBase` / `hoverSwapOverlay` — the two-layer crossfade pair used on the first
 *     slide only, when hover-swap is active. The `:hover` rule lives on `slide` itself (below)
 *     rather than on a dedicated wrapper part, since `slide` already establishes
 *     `position: relative` for every slide and an unmatched `[data-role]` selector on a
 *     non-hover-swap slide is a harmless no-op.
 *   - `badge` / `badgeLabel` — the merchandiser badge overlay, top-left of the image (Figma
 *     "Tag" > "touchContainer" > "Label", node confirmed identical across every Size/Type variant
 *     checked). Collapsed onto one wrapper rather than mirroring both Figma levels: the inner
 *     touchContainer only exists there to guarantee a tap target for an otherwise-interactive
 *     library component, and this badge is static text with nothing to tap.
 *     Figma's "Tag" is a *fixed* 48px-tall frame — exactly matching `close`'s own fixed 48px —
 *     with the text centred inside that fixed height, not padded outward by it. An earlier
 *     revision of this recipe used `paddingBlock` alone with no explicit height, which sizes the
 *     wrapper to padding + content instead (measured 64px) — same horizontal inset, but a
 *     genuinely different total height, so its centre-line landed 9px below `close`'s. Fixed by
 *     giving `badge` the same `height: var(--zimm-scale-1200)` (48px) `close` already uses, plus
 *     `display: flex; align-items: center` to centre the text within that fixed height the same
 *     way `close` centres its icon — not by padding.
 *   - `close` — the wishlist-remove overlay slot.
 *   - `carousel` / `arrowButton` — the desktop prev/next affordance.
 *   - `indicatorWrapper` — positions the composed ZimmSlideIndicator flush to the bottom edge.
 */
export const ZimmProductCardMedia = {
  parts: [
    'root',
    'scrollContainer',
    'slide',
    'image',
    'hoverSwapBase',
    'hoverSwapOverlay',
    'badge',
    'badgeLabel',
    'close',
    'carousel',
    'arrowButton',
    'indicatorWrapper',
  ],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    root: {
      position: 'relative',
      width: '100%',
    },

    scrollContainer: {
      display: 'flex',
      width: '100%',
      overflowX: 'auto',
      scrollSnapType: 'x mandatory',
      // Safari touch scrolling needs this for scroll-snap to feel native — same precedent as
      // the base SFCC product-scroller's own scrollProps.sx.
      WebkitOverflowScrolling: 'touch',
      // This is a paged card surface, not a general-purpose scroll region — the indicator/
      // arrows are the visible paging affordance, so the native scrollbar is suppressed.
      scrollbarWidth: 'none',
      '&::-webkit-scrollbar': { display: 'none' },
      // Direct, mandatory consequence of this element now taking `tabIndex={0}` when
      // keyboard-navigable — same uniform ring every other interactive ui-kits/ control uses
      // (zimmColourSwatch, zimmNavItem, zimmColourSwatchGroup's pageButton).
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    slide: {
      position: 'relative',
      flex: '0 0 100%',
      width: '100%',
      aspectRatio: ASPECT_RATIO,
      scrollSnapAlign: 'start',
      overflow: 'hidden',
      [HOVER_CAPABLE_QUERY]: {
        '&:hover [data-role="hover-overlay"]': { opacity: 1 },
        '&:hover [data-role="hover-base"]': { opacity: 0 },
      },
    },

    image: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
    },

    hoverSwapBase: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      position: 'absolute',
      inset: 0,
      opacity: 1,
      transition: 'opacity var(--zimm-motion-duration-default) var(--zimm-motion-easing-fades)',
    },

    hoverSwapOverlay: {
      display: 'block',
      width: '100%',
      height: '100%',
      objectFit: 'cover',
      position: 'absolute',
      inset: 0,
      opacity: 0,
      transition: 'opacity var(--zimm-motion-duration-default) var(--zimm-motion-easing-fades)',
    },

    badge: {
      position: 'absolute',
      top: 0,
      left: 0,
      // 48px — matches `close`'s own fixed height exactly, so both sit on the same vertical
      // centre-line (see this file's own docblock note above for why padding-only sizing broke
      // this).
      height: 'var(--zimm-scale-1200)',
      display: 'flex',
      alignItems: 'center',
      paddingInline: 'var(--zimm-scale-xl)', // 24px — Figma "Tag" horizontal inset
    },

    badgeLabel: {
      textStyle: 'caption',
      // Figma's own "Label" text node carries no uppercase transform, but confirmed badges are
      // uppercase regardless — applied explicitly rather than inherited from the node.
      textTransform: 'uppercase',
      color: 'var(--zimm-color-text-default)',
      whiteSpace: 'nowrap',
    },

    close: {
      position: 'absolute',
      top: 0,
      right: 0,
      width: 'var(--zimm-scale-1200)', // 48px — Figma "Close" overlay area
      height: 'var(--zimm-scale-1200)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'transparent',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem, zimmColourSwatchGroup's pageButton) — this overlay sits on top of a
      // photographic image with only the bare browser-default outline otherwise.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    carousel: {
      position: 'absolute',
      top: '50%',
      left: 0,
      right: 0,
      transform: 'translateY(-50%)',
      // Unconditionally `display: 'none'` at this Media-recipe level — no `[HOVER_CAPABLE_QUERY]`
      // override here anymore. A `[HOVER_CAPABLE_QUERY]: { display: 'flex' }` sub-block used to
      // live on this part, which made the arrows visible PERMANENTLY on any hover-capable device
      // (a device-CAPABILITY check, not an actual-hover check) — confirmed a real bug against the
      // Jira AC ("...when on desktop and the user hovers, then the arrows appear") and live Figma
      // (the Carousel element is `hidden="true"` on every Default-state instance checked, visible
      // only on the matching Hover-state instance, for both PLP and Wishlist). The real reveal now
      // lives entirely on `ZimmProductCard`'s own organism recipe (`zimmProductCard.css.ts`'s
      // `root` part), scoped to `:hover`/`:has(:focus-visible)` on the whole card, not just this image —
      // see that file's docblock point 6.
      display: 'none',
      justifyContent: 'space-between',
      alignItems: 'center',
      paddingInline: 'var(--zimm-scale-300)', // 12px — Figma arrow insets (x=12 / x=252 of 288)
      // Lets clicks pass through the empty centre of this band to whatever sits beneath the
      // image (e.g. a future PDP link in the Step 6 organism); re-enabled per-button below.
      pointerEvents: 'none',
    },

    arrowButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-600)', // 24px — Figma touchContainer, meets WCAG 2.5.8
      height: 'var(--zimm-scale-600)',
      background: 'transparent',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      pointerEvents: 'auto',
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem, zimmColourSwatchGroup's pageButton) — this overlay sits on top of a
      // photographic image with only the bare browser-default outline otherwise.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },

    indicatorWrapper: {
      position: 'absolute',
      left: 0,
      right: 0,
      bottom: 0,
      display: 'block',
      [HOVER_CAPABLE_QUERY]: {
        display: 'none',
      },
    },
  }),
};

