import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useHistory } from 'react-router-dom';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmColourSwatch } from '../../atoms/zimmColourSwatch';
import { ChevronLeftIcon, ChevronRightIcon } from '../../../icons';
import { SWATCHES_PER_PAGE } from './zimmColourSwatchGroupShared';

const messages = defineMessages({
  groupLabel: { id: 'colour_swatches.group.label', defaultMessage: 'Colour' },
  label: { id: 'colour_swatches.label', defaultMessage: 'Colour:' },
  paginationGroupLabel: { id: 'colour_swatches.pagination.group_label', defaultMessage: 'Colour swatch pages' },
  next: { id: 'colour_swatches.pagination.next', defaultMessage: 'Next colours' },
  previous: { id: 'colour_swatches.pagination.previous', defaultMessage: 'Previous colours' },
});

const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';

/** One selectable colour variation as the molecule expects it — pre-mapped from the raw SFCC shape. */
export type ZimmColourSwatchValue = {
  value: string;
  name: string;
  /** Resolved swatch fill image URL. Absence means the colour has no swatch image and is withheld. */
  imageUrl?: string;
  /** Router destination URL for this colour. Absent on the quick-view modal path. */
  href?: string;
  /** Mirrors SFCC's `orderable` flag. Unavailable colours are withheld (not shown as disabled). */
  orderable?: boolean;
  /**
   * When true, clicking navigates via a native anchor (full page reload) rather than a router
   * Link. Set for related-colour swatches (SFCC-708) that link to a different master product.
   */
  forceReload?: boolean;
};

type ZimmColourSwatchGroupProps = {
  values: ZimmColourSwatchValue[];
  /** Currently selected colour value (from URL / variation params). */
  selectedValue?: string;
  /**
   * Display label for the colour group. Defaults to the i18n "Colour" value.
   * Pass an explicit value when the SFCC attribute display name differs from the default.
   */
  label?: string;
  /**
   * Selection callback for the linkless path (no `href` on values). Called on click and
   * arrow-key navigation. Not needed on the PDP, where each value carries an `href` and
   * selection is handled by router navigation.
   */
  onSelect?: (value: string) => void;
};

/**
 * Molecule — the full colour-swatch group: label row (name + pagination arrows), and a
 * `[role=radiogroup]` swatch strip of `ZimmColourSwatch` atoms with roving tabindex and
 * keyboard navigation.
 *
 * When only one offered colour exists, the label and name render but the swatch row is
 * suppressed (nothing to choose between). Colours without a swatch image or marked
 * non-orderable are withheld entirely.
 */
export const ZimmColourSwatchGroup = ({ values, selectedValue, label, onSelect }: ZimmColourSwatchGroupProps) => {
  const intl = useIntl();
  const groupLabel = label ?? intl.formatMessage(messages.groupLabel);
  const labelText = label != null ? `${label}:` : intl.formatMessage(messages.label);

  // Filter to only offered (orderable + swatch image populated) colours.
  const offered = values.filter((v) => Boolean(v.imageUrl) && v.orderable !== false);

  const isPaginated = offered.length > SWATCHES_PER_PAGE;
  const pageCount = Math.ceil(offered.length / SWATCHES_PER_PAGE);

  const [page, setPage] = useState(0);

  // Auto-advance to the page containing the pre-selected value on mount or when selectedValue
  // changes (e.g. browser back/forward lands on a colour that is off page 0).
  // When selectedValue is absent or not in the offered set, clamp to the highest valid page so
  // all remaining swatches stay visible after the offered set shrinks (e.g. a colour becomes
  // unavailable while the user is on a later page).
  useEffect(() => {
    const idx = offered.findIndex((v) => v.value === selectedValue);
    if (idx >= 0) {
      setPage(Math.floor(idx / SWATCHES_PER_PAGE));
    } else {
      const pc = Math.ceil(offered.length / SWATCHES_PER_PAGE);
      setPage((p) => Math.min(p, Math.max(0, pc - 1)));
    }
    // offered.length captures filter changes; selectedValue tracks URL/prop changes.
  }, [selectedValue, offered.length]);

  // Roving tabindex: the focused atom is either the selected one or index 0 (no selection).
  const selectedIndex = offered.findIndex((v) => v.value === selectedValue);
  const tabFocusIndex = selectedIndex >= 0 ? selectedIndex : 0;

  // True when the globally-selected swatch falls on the current visual page.
  const isTabFocusOnPage = Math.floor(tabFocusIndex / SWATCHES_PER_PAGE) === page;

  // Focus management after keyboard navigation. After history.push updates the URL and React
  // re-renders with a new selectedValue, focus the newly-focusable atom imperatively so the
  // shopper doesn't have to re-tab to continue arrow-key navigation.
  const radioGroupRef = useRef<HTMLDivElement>(null);
  const hasNavigated = useRef(false);

  useEffect(() => {
    if (hasNavigated.current) {
      const focusable = radioGroupRef.current?.querySelector('[tabindex="0"]') as HTMLElement | null;
      focusable?.focus();
      hasNavigated.current = false;
    }
  }, [selectedValue]);

  const history = useHistory();

  const handleSwatchesKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();

    // Derive current index from the focused element's data-swatch-value — a unique value
    // identity that survives duplicate display names (e.g. two shades both named "Bay Blue").
    const focusedValue = (document.activeElement as HTMLElement | null)
      ?.closest('[data-swatch-value]')
      ?.getAttribute('data-swatch-value');
    const focusedIndex = focusedValue ? offered.findIndex((v) => v.value === focusedValue) : -1;
    const currentIndex = focusedIndex >= 0 ? focusedIndex : tabFocusIndex;

    const isForward = e.key === 'ArrowRight' || e.key === 'ArrowDown';
    const nextIndex = isForward
      ? (currentIndex + 1) % offered.length
      : (currentIndex - 1 + offered.length) % offered.length;

    const next = offered[nextIndex];
    const nextPage = Math.floor(nextIndex / SWATCHES_PER_PAGE);

    setPage(nextPage);
    hasNavigated.current = true;

    if (next.href) {
      if (next.forceReload) {
        window.location.href = next.href;
      } else {
        history.push(next.href);
      }
    } else {
      onSelect?.(next.value);
    }
  };

  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated });

  const selectedName = offered.find((v) => v.value === selectedValue)?.name ?? offered[0]?.name;

  // No offered colours at all (every value failed the imageUrl/orderable filter) — suppress
  // the entire group including the label so a bare "Colour:" never appears on the PDP.
  if (offered.length === 0) return null;

  return (
    <chakra.div __css={styles.root}>
      <chakra.div __css={styles.label}>
        <chakra.span textStyle="caption">{labelText}</chakra.span>
        {selectedName && (
          <chakra.span data-testid="pdp-colour-selected-name" __css={styles.labelName}>
            {selectedName}
          </chakra.span>
        )}
        {isPaginated && (
          <chakra.div __css={styles.pagination} aria-label={intl.formatMessage(messages.paginationGroupLabel)}>
            <chakra.button
              as="button"
              __css={styles.pageButton}
              aria-label={intl.formatMessage(messages.previous)}
              disabled={page === 0}
              onClick={() => setPage((p) => p - 1)}
            >
              <ChevronLeftIcon aria-hidden />
            </chakra.button>
            <chakra.button
              as="button"
              __css={styles.pageButton}
              aria-label={intl.formatMessage(messages.next)}
              disabled={page === pageCount - 1}
              onClick={() => setPage((p) => p + 1)}
            >
              <ChevronRightIcon aria-hidden />
            </chakra.button>
          </chakra.div>
        )}
      </chakra.div>

      {offered.length > 1 && (
        <chakra.div
          role="radiogroup"
          aria-label={groupLabel}
          ref={radioGroupRef}
          __css={styles.swatches}
          onKeyDown={handleSwatchesKeyDown}
        >
          {offered.map((v, i) => {
            const isOnPage = Math.floor(i / SWATCHES_PER_PAGE) === page;
            // Off-page swatches are always removed from the tab order (tabIndex="-1"), even
            // when they're the globally-selected colour, so Tab focus never lands on a
            // visually-hidden element. When the selected swatch is off-page (the user manually
            // paged without changing colour), the first on-page swatch becomes the tab stop.
            const isFocusable = isOnPage && (isTabFocusOnPage ? i === tabFocusIndex : i === page * SWATCHES_PER_PAGE);

            return (
              // All swatches are always in the DOM so screen readers can navigate the full set
              // and aria-posinset/aria-setsize reports the correct total count ("N of M" where
              // M = all offered colours, not just the current page). Off-page swatches are
              // absolutely positioned — removed from the flex flow so they don't widen the row —
              // and clip-path'd to a 0×0 visible area so they are invisible on screen while
              // remaining in the accessibility tree.
              <chakra.span
                key={v.value}
                data-swatch-value={v.value}
                style={isOnPage ? undefined : { position: 'absolute', clipPath: 'inset(50%)' }}
              >
                <ZimmColourSwatch
                  name={v.name}
                  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
                  imageUrl={v.imageUrl!}
                  href={v.href}
                  forceReload={v.forceReload}
                  onClick={onSelect ? () => onSelect(v.value) : undefined}
                  isSelected={v.value === selectedValue}
                  isFocusable={isFocusable}
                  posInSet={i + 1}
                  setSize={offered.length}
                />
              </chakra.span>
            );
          })}
        </chakra.div>
      )}
    </chakra.div>
  );
};

export default ZimmColourSwatchGroup;

import type { SystemStyleObject } from '@chakra-ui/react';
import { SWATCHES_PER_PAGE } from './zimmColourSwatchGroupShared';

/**
 * Recipe for the PDP colour-swatch group — the "Colour: Bay Blue" label row, and (when there is
 * more than one populated colour) the row of ZimmColourSwatch rectangles beneath it. This recipe
 * only lays the group out; each swatch's own fill/border/focus styling stays in the sibling
 * ZimmColourSwatch atom's own recipe.
 *
 * Values below are read directly off Figma for this exact component, not estimated — node
 * 40000307:13867 ("ColourOptions"), within Zimmermann_Design_System_2026.
 *
 * Six parts:
 *   - `root` — outer vertical flex container: the label row above, the swatches row below.
 *     Capped to a fixed `maxWidth` (`GROUP_RESERVED_WIDTH`, see below) unconditionally — not just
 *     when paginated — so `labelName`'s truncation CSS always has a definite width to truncate
 *     against. See this part's own baseStyle comment for the full explanation.
 *   - `label` — the label row ("labelContainer" in Figma): the label-group (the two
 *     "Colour:"/name text pieces — laid out via a plain Chakra-prop wrapper in the component
 *     itself, not a seventh part here; see index.tsx's own comment for why) plus the pagination
 *     controls, right-aligned purely via the label-group's own `flex: 1 0 0` rather than an
 *     absolute-position hack.
 *   - `labelName` — the dynamic colour-name text specifically (e.g. "Bay Blue"). Gets its own
 *     part, unlike the static "Colour:" piece beside it, because it alone carries the
 *     Figma-mandated truncation behaviour: "If Label/Colour name is longer, use truncation"
 *     (this node's own interaction annotation).
 *   - `swatches` — the horizontal row of rendered ZimmColourSwatch children. Once paginated
 *     (`isPaginated`), reserves a fixed page-width footprint regardless of how many items the
 *     current window actually renders — see its own baseStyle comment below for the layout bug
 *     this prevents.
 *   - `pagination` — wrapper around the two chevron buttons.
 *   - `pageButton` — each individual chevron button (24x24, holding a 16px ZimmIcon).
 */

/**
 * Imported from the shared zimmColourSwatchGroupShared.ts module — the same shared-module
 * precedent theme/components/footerShared.ts already sets — rather than retyped here, so
 * index.tsx, this recipe, and the test file can never disagree with each other. Aliased to the
 * shorter `PAGE_SIZE` name since this file's only use is the `GROUP_RESERVED_WIDTH` calc
 * expression below.
 */
const PAGE_SIZE = SWATCHES_PER_PAGE;

/**
 * The reserved 4-swatch-wide footprint: PAGE_SIZE swatches at the atom's own fixed 47px width
 * (see `swatch.width` in zimmColourSwatch.css.ts), with no per-swatch gap
 * (`swatches.gap` below is 0, same as the atom's own adjacency). Two consumers share this one
 * value rather than each typing their own copy of the same `calc(...)` expression:
 *   - `swatches.width`/`minWidth`, applied only once paginated (see that part below) — keeps the
 *     footprint constant across a full page vs. a shorter final page.
 *   - `root.maxWidth`, applied unconditionally regardless of pagination (see that part below) —
 *     caps the whole component so `labelName`'s truncation CSS always has a definite width to
 *     truncate against.
 */
const GROUP_RESERVED_WIDTH = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;

export const ZimmColourSwatchGroup = {
  parts: ['root', 'label', 'labelName', 'swatches', 'pagination', 'pageButton'],

  baseStyle: ({ isPaginated }: { isPaginated?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      flexDirection: 'column',
      // 8px between the label row and the swatches row. No background here — background lives
      // per-swatch, already handled by the atom's own recipe.
      gap: 'var(--zimm-scale-xs)',
      // Unconditional cap, regardless of `isPaginated` — this is a bug fix, not a stylistic
      // choice. `root` otherwise has no width of its own (deliberate — see the `swatches` part
      // below for why a short, non-paginated row must still size naturally to its actual content)
      // so it has no ceiling for `labelName`'s truncation CSS to truncate against: confirmed via
      // real Chromium rendering that a long enough colour name simply grows `root` (and the
      // flex-grown `labelName` span inside it) past this footprint with no ellipsis, unless some
      // ancestor happens to impose a definite width of its own. Capping `root` itself to the same
      // reserved footprint `swatches` already reserves once paginated makes truncation
      // self-contained in every context, rather than depending on whatever the eventual PDP page
      // does or doesn't constrain. `maxWidth`, not `width`: `root` must still be free to render
      // narrower than this when content is short (e.g. one or two short colour names) — this only
      // ever stops it from growing past the cap. Does not change the swatches row's own sizing
      // behaviour (still `100%` when non-paginated, see below) — it only changes what that `100%`
      // now resolves against.
      maxWidth: GROUP_RESERVED_WIDTH,
    },

    label: {
      display: 'flex',
      alignItems: 'center',
      // 24px. Matches spacing.xl exactly, so the named step is used rather than the numerically
      // identical --zimm-scale-600 alias — see bottomBar.css.ts's own `var(--zimm-scale-xl)`
      // usage for the same 24px value elsewhere in this codebase.
      height: 'var(--zimm-scale-xl)',
      // 8px between the label-group and the pagination controls.
      gap: 'var(--zimm-scale-xs)',
    },

    labelName: {
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
      // The truncating half of the label-group's two text pieces (the static "Colour:" text
      // beside it never truncates — see index.tsx). `flex: 1 0 0` lets it consume the
      // label-group's remaining width; `minWidth: 0` is required for a flex item to actually
      // shrink below its content size instead of overflowing; the rest is the standard
      // single-line-ellipsis triad.
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
    },

    swatches: {
      display: 'flex',
      // Required so that off-page swatches (position:absolute, see index.tsx) are contained
      // within this element rather than escaping to the nearest positioned ancestor.
      position: 'relative',
      // Non-paginated (<= SWATCHES_PER_PAGE populated colours): sizes naturally to however many
      // swatches are actually present. Unchanged, deliberately out of scope for this fix — there
      // is no confirmed design value either way for a 2- or 3-colour row's width, so nothing was
      // invented here.
      //
      // Paginated (> SWATCHES_PER_PAGE populated colours, windowed to a fixed PAGE_SIZE-wide
      // slice per page): a plain `100%` here resolves against `root`'s own width — but `root` has
      // no explicit width of its own, so it auto-fits to its widest child, which is this very
      // element. That circular relationship meant the *rendered* width tracked how many items the
      // current window actually held (192px for a full 4-item page, 96px for a 2-item final
      // page), so `root` — and `label` above it, itself 100% of that same `root` — visibly
      // resized between pages. Confirmed directly in a running Storybook: the pagination chevrons
      // jumped position between the two pages of the `Paginated` story. Reserving
      // GROUP_RESERVED_WIDTH regardless of the current page's real item count breaks that
      // loop — the footprint stays constant across every page, full or partial. A partial final
      // page's unused space simply remains empty to the right: the flex default
      // `justify-content: flex-start` already left-aligns the rendered items, so nothing further
      // is needed for that.
      width: isPaginated ? GROUP_RESERVED_WIDTH : '100%',
      ...(isPaginated ? { minWidth: GROUP_RESERVED_WIDTH } : {}),
      // Confirmed directly off the Figma export, not a stylistic default: the 4-swatch example
      // measures exactly 192px total width for four 48px-wide swatches (4 x 48, no gap
      // contribution) — swatches sit directly adjacent. Do not add a gap here; that would be a
      // real deviation from the design, not a stylistic default.
      gap: 0,
    },

    pagination: {
      display: 'flex',
      alignItems: 'center',
      // No inter-button gap value exists in the Figma export handed to this step — left at the
      // flex default (no `gap` declared at all) rather than invented. Revisit if a designer
      // confirms a real value.
    },

    pageButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-xl)', // 24px
      height: 'var(--zimm-scale-xl)', // 24px
      // Resets the native <button> UA chrome so the box is exactly the 24x24 the design calls
      // for, with the 16px ZimmIcon centred inside it by the flex alignment above.
      padding: 0,
      border: 'none',
      background: 'none',
      cursor: 'pointer',
      // No confirmed Figma spec for a disabled visual treatment on this control — same "leave an
      // unspecified visual state alone rather than invent one" precedent as swatch-group's own
      // disabled colour logic (see this codebase's Known Gaps notes). The native `disabled`
      // attribute (set in index.tsx) already makes the control genuinely inert and announces as
      // disabled to assistive tech; only the cursor affordance is set here, which is a UX
      // keyword, not a design token.
      _disabled: {
        cursor: 'not-allowed',
        color: 'var(--zimm-color-icon-disabled)',
      },
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem) — --zimm-focus-ring already composites the border-width/colour pair.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  }),
};

import type { SystemStyleObject } from '@chakra-ui/react';
// Shared with zimmProductCard.css.ts's own identical need (its PLP bag-icon mobile hide) —
// extracted to zimmProductCardShared.ts for the same reason HOVER_CAPABLE_QUERY already is there:
// a module-private copy in each file is exactly the same-value-typed-twice drift risk a shared
// constant removes. See that module's own comment for why the underlying breakpoints token has
// to be imported directly rather than referenced as var(--zimm-*) — media queries can't consume
// CSS custom properties.
import { DESKTOP_QUERY } from '../../zimmProductCardShared';

/** State the atom feeds in so the recipe can resolve the bag button's disabled treatment —
 *  named `disabled`, not `isUnavailable`, to match `recipeGuards.test.ts`'s own
 *  `DEFAULT_STYLE_PROPS` key so that guard's exhaustive prop-combination walk actually exercises
 *  both branches. Same reasoning `zimmSizeChip.css.ts` documents for its own `disabled` prop. */
type ZimmProductCardContentStyleProps = {
  disabled?: boolean;
};

// Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
// zimmNavItem, zimmColourSwatchGroup's pageButton, zimmProductCardMedia's close/arrowButton/
// scrollContainer) — no Figma spec exists for focus on any of this component's three
// interactive parts (nameLink, bagButton, notifyMeButton), same situation those precedents were
// already in. This gap was caught twice already in this build (Step 2, Step 4); not repeating it.
const FOCUS_VISIBLE: SystemStyleObject = {
  outline: 'var(--zimm-focus-ring)',
  outlineOffset: 'var(--zimm-focus-ring-offset-default)',
};

/**
 * Recipe for the product-card text-content block (ui-kits/molecules/zimmProductCardContent).
 * Figma "Card-content" component set, node 40002109:26908 (Desktop 40002109:26906).
 *
 * Vertical rhythm is expressed as `marginTop` on each row rather than a uniform `root.gap`,
 * because the confirmed Figma offsets are NOT uniform:
 *   - 16px between the name row (height 25) and the attributes row (starts at y=41): 41-25=16.
 *   - 24px between the name+attributes block (height 49) and the price (starts at y=73): 73-49=24.
 *   - 24px between the price frame (height 82) and the (hidden by default) size-selector slot
 *     (starts at y=106): 106-82=24.
 * These margins apply regardless of which sibling actually precedes a given row (e.g. price's
 * marginTop is the same whether or not the attributes row rendered above it) — no distinct value
 * is confirmed for that specific combination, so the same rhythm is reused rather than invented.
 *
 * `root`'s outer padding IS genuinely responsive — a real, confirmed gap, not a missing
 * responsive split on an otherwise-correct single value. An earlier revision of this docblock
 * asserted nothing correctness-critical differed by breakpoint and shipped `root` with no
 * padding at all, on any breakpoint; that claim was never actually checked against the Mobile
 * variant and is corrected now that it has been. Confirmed via get_design_context on the two
 * real assembled card instances (not just the standalone documentation set):
 *   - Desktop (node 40002163:41443, the real assembled Desktop/Default/PLP-PDP card's
 *     Card-content): padding-top 32px, padding-inline 40px.
 *   - Mobile (node 40002163:37103, the Mobile Card-content variant): padding-top 16px,
 *     padding-inline 32px.
 * These are genuinely different values, not the same padding read at a smaller viewport, so
 * `root` carries an explicit `DESKTOP_QUERY` step (mobile-first: the
 * base values are the Mobile ones, overridden at the desktop breakpoint) rather than a single
 * baseStyle value — see .claude/rules/overrideStyling.md's "explicit media queries, not
 * Chakra's array shorthand" rule.
 *
 * Parts:
 *   - `root` — the outermost flex column; carries the responsive outer padding above.
 *   - `nameRow` — Figma's "Product name and icons": the heading link + bag icon, space-between.
 *   - `nameLink` — the router `<Link>` wrapping the composed ZimmProductName heading.
 *   - `bagWrapper` / `bagButton` — Figma's "Icons" group and its 24x24 `touchContainer` button.
 *   - `attributesRow` / `colourText` / `sizeText` — the wishlist-only colour/size meta line.
 *   - `priceWrapper` — wraps the composed ZimmProductPrice (always rendered).
 *   - `sizeChipWrapper` — wraps the composed ZimmSizeChipGroup (PLP-only when rendered at all).
 *   - `notifyMeButton` — the out-of-stock notify-me CTA, the shared CTA/Link atom instance
 *     (Figma node 40002163:41468; full citation in index.tsx).
 */
export const ZimmProductCardContent = {
  parts: [
    'root',
    'nameRow',
    'nameLink',
    'bagWrapper',
    'bagButton',
    'attributesRow',
    'colourText',
    'sizeText',
    'priceWrapper',
    'sizeChipWrapper',
    'notifyMeButton',
  ],

  baseStyle: ({ disabled }: ZimmProductCardContentStyleProps): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      // Mobile-first base values — Figma node 40002163:37103 (Mobile Card-content variant).
      // See the module docblock above for the full citation and why this genuinely differs by
      // breakpoint rather than collapsing to one value.
      paddingTop: 'var(--zimm-scale-m)', // 16px
      paddingInline: 'var(--zimm-scale-2xl)', // 32px
      [DESKTOP_QUERY]: {
        // Desktop override — Figma node 40002163:41443 (Desktop/Default/PLP-PDP Card-content).
        paddingTop: 'var(--zimm-scale-2xl)', // 32px
        paddingInline: 'var(--zimm-scale-3xl)', // 40px
      },
    },

    nameRow: {
      display: 'flex',
      // 'center', not Figma codegen's own `items-start` approximation for this auto-layout row:
      // the "Card heading" (name) and "Icons" touchContainer resolve to different effective
      // heights in the real assembled card (name: 8px padding around a 16px line-height ≈ 32px;
      // icon: 4px padding around a 16px icon = 24px) — confirmed via get_design_context on node
      // 40002163:41441, the real assembled Desktop/Default/PLP-PDP card, not just the standalone
      // documentation set. Top-aligning two different-height children produces a visible ~4px
      // offset between the icon's optical centre and the name text's optical centre; `center` is
      // the robust way to align a text label against a differently-sized icon button in a
      // horizontal flex row, and matches what the design visually shows.
      alignItems: 'center',
      justifyContent: 'space-between',
      // 8px — Figma: the 24px icon column starts at x=184 inside the 208px row, and the name
      // column is 176px wide (208 - 176 - 24 = 8).
      gap: 'var(--zimm-scale-xs)',
    },

    nameLink: {
      display: 'block',
      flex: '1 1 auto',
      minWidth: 0,
      color: 'inherit',
      textDecoration: 'none',
      _focusVisible: FOCUS_VISIBLE,
    },

    bagWrapper: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexShrink: 0,
    },

    bagButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-600)', // 24px — Figma touchContainer, meets WCAG 2.5.8
      height: 'var(--zimm-scale-600)',
      background: 'transparent',
      border: 'none',
      padding: 0,
      color: disabled ? 'var(--zimm-color-text-muted)' : 'var(--zimm-color-text-default)',
      cursor: disabled ? 'not-allowed' : 'pointer',
      _focusVisible: FOCUS_VISIBLE,
    },

    attributesRow: {
      display: 'flex',
      alignItems: 'center',
      // 2px — confirmed via get_design_context on node 40002187:58446 (the real Wishlist
      // Card-content instance): the Attributes container's two text children have an explicit
      // `gap-[2px]` between them. Supersedes an earlier placeholder (`--zimm-scale-2xs`, 4px)
      // that was reused from zimmProductStyleCode.css.ts's label/value gap on the assumption
      // that "no horizontal offset is given" in Figma for this pair — a real value exists now.
      gap: 'var(--zimm-scale-3xs)',
      marginTop: 'var(--zimm-scale-m)', // 16px — see docblock above
    },

    colourText: {
      margin: 0,
      // Matches zimmProductStyleCode.css.ts's meta-text treatment: caption size + secondary
      // colour, deliberately quieter than the product name above it.
      textStyle: 'caption',
      color: 'var(--zimm-color-text-secondary)',
    },

    sizeText: {
      margin: 0,
      textStyle: 'caption',
      color: 'var(--zimm-color-text-secondary)',
    },

    priceWrapper: {
      marginTop: 'var(--zimm-scale-xl)', // 24px — see docblock above
    },

    // Deliberately no `display` value at all here — Figma's `hidden=true` default on this slot
    // is the Step 6 organism's hover-reveal CSS to implement on top of this component's always-
    // rendered output, not something this component's own recipe enforces (see index.tsx's
    // data-card-slot contract comment). Setting `display: 'none'` here would fight whatever the
    // organism's hover-reveal CSS tries to do.
    sizeChipWrapper: {
      marginTop: 'var(--zimm-scale-xl)', // 24px — see docblock above
    },

    notifyMeButton: {
      // 24px — matches priceWrapper/sizeChipWrapper's own marginTop above: Figma's "Content"
      // wrapper (the flex column holding name-block, price, and this notify-me link) applies a
      // uniform 24px gap between ALL direct children, confirmed via get_design_context on node
      // 40002163:41470 (Desktop, Hover, PLP/PDP, Unavailable=True). Supersedes an earlier
      // placeholder value shipped before this was confirmed.
      marginTop: 'var(--zimm-scale-xl)',
      display: 'block',
      background: 'transparent',
      border: 'none',
      padding: 0,
      textAlign: 'left',
      textStyle: 'linkSm',
      // alias/color/link/default (Figma) — not text/default, even though both resolve to the
      // same hex in this palette. Confirmed via get_design_context on node 40002163:41468, the
      // "CTA/Link" atom instance (40001908:28374/40001908:28368) this control reuses.
      color: 'var(--zimm-color-link-default)',
      cursor: 'pointer',
      _focusVisible: FOCUS_VISIBLE,
    },
  }),
};

